import * as THREE from './vendor/three.module.js';
let goalParts=null,ballPart=null;const textures={};
export const pitchTypes={dirt:{label:'Street sand',drag:.9,bounce:.4,color:0xb88e67},concrete:{label:'Concrete court',drag:.36,bounce:.66,color:0xb0a690},grass:{label:'Grass pitch',drag:1.15,bounce:.48,color:0x9aa765}};
export function pitchType(game,setting='auto'){return pitchTypes[setting]?setting:game==='fourcorners'?'concrete':game==='penalties'?'grass':'dirt';}
export async function loadFootballAssets(){const loader=new THREE.TextureLoader();await Promise.all(Object.entries({grass:'grass.jpg',concrete:'concrete.jpg',concreteNormal:'concrete-normal.png',net:'netting.png',ball:'ball.png'}).map(async([key,file])=>{const t=await loader.loadAsync('assets/football/'+file);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=8;t.userData.sharedAsset=true;if(key!=='concreteNormal')t.colorSpace=THREE.SRGBColorSpace;textures[key]=t;}));const response=await fetch('assets/football/goal.json');if(!response.ok)throw new Error('Football goal asset unavailable');const data=await response.json();goalParts=data.meshes.map(p=>{const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(p.positions,3));geometry.setAttribute('normal',new THREE.Float32BufferAttribute(p.normals,3));geometry.setAttribute('uv',new THREE.Float32BufferAttribute(p.uv,2));geometry.setIndex(p.indices);const material=p.material==='net'?new THREE.MeshStandardMaterial({map:textures.net,transparent:true,alphaTest:.45,side:THREE.DoubleSide,roughness:.9,color:0xd7d2bd}):new THREE.MeshStandardMaterial({color:0xe6ddc7,roughness:.58,metalness:.16});return {geometry,material,name:p.name,net:p.material==='net'};});const ballResponse=await fetch('assets/football/ball.json');if(!ballResponse.ok)throw new Error('Football asset unavailable');const b=(await ballResponse.json()).meshes[0],geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(b.positions,3));geometry.setAttribute('normal',new THREE.Float32BufferAttribute(b.normals,3));geometry.setAttribute('uv',new THREE.Float32BufferAttribute(b.uv,2));geometry.setIndex(b.indices);ballPart={geometry,material:new THREE.MeshStandardMaterial({map:textures.ball,roughness:.72,color:0xffffff})};}
export function footballGoal(width=5,height=2.5,depth=1.1){if(!goalParts)return null;const root=new THREE.Group(),net=new THREE.Group();root.add(net);for(const part of goalParts){const m=new THREE.Mesh(part.geometry,part.material);m.name=part.name;m.userData.sharedAsset=true;m.castShadow=!part.net;m.receiveShadow=true;(part.net?net:root).add(m);}root.scale.set(width/7.32,height/2.44,depth/2.5503);root.userData.net=net;root.userData.source='Gameplay Football / Unlicense';return root;}
export function pitchSurface(root,w,d,type='dirt'){if(type==='dirt')return;const texture=textures[type]?.clone();if(texture){texture.repeat.set(w/4,d/4);texture.userData.sharedAsset=false;}const normal=type==='concrete'?textures.concreteNormal?.clone():null;if(normal){normal.repeat.set(w/4,d/4);normal.userData.sharedAsset=false;}const material=new THREE.MeshStandardMaterial({map:texture||null,normalMap:normal||null,normalScale:new THREE.Vector2(.22,.22),color:pitchTypes[type].color,roughness:.96,polygonOffset:true,polygonOffsetFactor:1,polygonOffsetUnits:1});const plane=new THREE.Mesh(new THREE.PlaneGeometry(w,d),material);plane.rotation.x=-Math.PI/2;plane.position.y=.004;plane.receiveShadow=true;root.add(plane);}

export function footballBall(parent,r=.12){if(!ballPart)return null;const mesh=new THREE.Mesh(ballPart.geometry,ballPart.material);mesh.scale.setScalar(r);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.sharedAsset=true;mesh.userData.radius=r;parent.add(mesh);return mesh;}
